CREATE OR REPLACE FUNCTION public.fn_ca_ledger_replay(p_limit integer DEFAULT 5000)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
 SET statement_timeout TO '540s'
AS $function$
  DECLARE
    v_now timestamptz := clock_timestamp();
    v_read_at timestamptz;
    /* v4 (2026-09-10): THE JOURNAL WINDOW IS A SNAPSHOT, NOT A CLOCK. A leg
       whose transaction straddled the previous reading (created_at before the
       reading, committed after it) fell through the created_at window for
       ever and read as drift (-100 / +100 on 2026-09-10). Every reading now
       records the snapshot it read under; the next reading counts a leg iff it
       was not visible in that snapshot. Every account rebaselines once. */
    v_basis text := 'one-snapshot-v4';
    r record; w record;
    v_entities uuid[];
    v_checked int := 0; v_baselines int := 0; v_rebased int := 0;
    v_bad int := 0; v_unkeyable bigint := 0;
    v_this numeric; v_two numeric; v_cum numeric;
    v_worst numeric := 0; v_worst_key text; v_sample jsonb := '[]'::jsonb;
  BEGIN
    IF NOT (current_user IN ('postgres', 'supabase_admin') OR COALESCE(auth.role(), '') = 'service_role') THEN
      RAISE EXCEPTION 'fn_ca_ledger_replay is service only' USING ERRCODE = '42501';
    END IF;

    DROP TABLE IF EXISTS zz_replay_window;
    DROP TABLE IF EXISTS zz_replay_touched;
    DROP TABLE IF EXISTS zz_replay_prev;
    DROP TABLE IF EXISTS zz_replay_net;
    DROP TABLE IF EXISTS zz_replay_read;

    CREATE TEMP TABLE zz_replay_window ON COMMIT DROP AS
      SELECT a.* FROM public.fn_ca_leg_accounts(v_now - interval '26 hours', v_now) a;

    SELECT COALESCE(sum(zw.unkeyable), 0) INTO v_unkeyable FROM zz_replay_window zw WHERE zw.account_type = 'unkeyable';

    CREATE TEMP TABLE zz_replay_touched ON COMMIT DROP AS
      SELECT zw.* FROM zz_replay_window zw
       WHERE zw.account_type <> 'unkeyable'
       ORDER BY abs(zw.net) DESC
       LIMIT GREATEST(COALESCE(p_limit, 5000), 1);

    CREATE TEMP TABLE zz_replay_prev ON COMMIT DROP AS
      SELECT t.account_key, s.balance AS prev_balance, s.taken_at AS prev_at,
             s.unexplained AS prev_unexplained, s.cum_unexplained AS prev_cum,
             s.basis_version AS prev_basis, s.read_snapshot AS prev_snapshot
        FROM zz_replay_touched t
        LEFT JOIN LATERAL (
          SELECT x.balance, x.taken_at, x.unexplained, x.cum_unexplained, x.basis_version, x.read_snapshot
            FROM public.ca_account_snapshots x
           WHERE x.account_key = t.account_key ORDER BY x.taken_at DESC LIMIT 1
        ) s ON true;

    /* THE BALANCE, THE JOURNAL AND THE SNAPSHOT ARE READ IN ONE STATEMENT.
       read_snapshot is pg_current_snapshot() evaluated by that statement, so
       it is exactly the visibility horizon the balances were read under, and
       it becomes the next run's window. */
    CREATE TEMP TABLE zz_replay_read (
      account_key text, prev_at timestamptz, prev_snapshot text, expected numeric,
      now_bal numeric, read_at timestamptz, read_snapshot text
    ) ON COMMIT DROP;

    /* EACH WINDOW READS ONLY THE LEGS IT IS ASKED ABOUT (2026-10-03). Accounts
       are grouped by the reading they were last judged at, and each group's
       journal window runs from that reading to now, over the whole journal.
       On 2026-10-03 five groups last read between 09-23 and 09-30 asked for
       about 27 days of it - some 30 million leg sides - to explain 65 idle
       accounts: the run grew from 323 s to 627 s in five nights and was
       cancelled at its 600 s budget. A group now reads, through the entity index,
       only the legs of the owners it holds (and a union's wallet row ids,
       which its legs may carry). The felt is one account owned by no entity,
       so the group that holds it still reads the whole window; that group is
       the one read last night, the shortest window of all. */
    FOR w IN SELECT p.prev_at, p.prev_snapshot,
                    bool_or(t.account_type = 'table_stack') AS reads_the_felt,
                    array_agg(DISTINCT t.entity_id) AS owners
               FROM zz_replay_prev p
               JOIN zz_replay_touched t ON t.account_key = p.account_key
              WHERE p.prev_at IS NOT NULL AND p.prev_snapshot IS NOT NULL
              GROUP BY p.prev_at, p.prev_snapshot LOOP
      v_read_at := clock_timestamp();
      IF w.reads_the_felt THEN
        WITH legs AS MATERIALIZED (
          SELECT a.account_key, a.net
            FROM public.fn_ca_leg_accounts_since_snapshot(w.prev_at, w.prev_snapshot::pg_snapshot) a
           WHERE a.account_key IS NOT NULL
        )
        INSERT INTO zz_replay_read (account_key, prev_at, prev_snapshot, expected, now_bal, read_at, read_snapshot)
        SELECT t.account_key, w.prev_at, w.prev_snapshot, COALESCE(l.net, 0),
               public.fn_ca_account_balance(t.account_type, t.entity_id, t.club_id, t.column_name),
               v_read_at, pg_current_snapshot()::text
          FROM zz_replay_touched t
          JOIN zz_replay_prev p ON p.account_key = t.account_key AND p.prev_at = w.prev_at
                               AND p.prev_snapshot = w.prev_snapshot
          LEFT JOIN legs l ON l.account_key = t.account_key;
      ELSE
        v_entities := w.owners
          || ARRAY(SELECT uw.id FROM public.union_wallets uw WHERE uw.union_id = ANY (w.owners));
        WITH legs AS MATERIALIZED (
          SELECT a.account_key, a.net
            FROM public.fn_ca_leg_accounts_since_snapshot_for(w.prev_at, w.prev_snapshot::pg_snapshot, v_entities) a
           WHERE a.account_key IS NOT NULL
        )
        INSERT INTO zz_replay_read (account_key, prev_at, prev_snapshot, expected, now_bal, read_at, read_snapshot)
        SELECT t.account_key, w.prev_at, w.prev_snapshot, COALESCE(l.net, 0),
               public.fn_ca_account_balance(t.account_type, t.entity_id, t.club_id, t.column_name),
               v_read_at, pg_current_snapshot()::text
          FROM zz_replay_touched t
          JOIN zz_replay_prev p ON p.account_key = t.account_key AND p.prev_at = w.prev_at
                               AND p.prev_snapshot = w.prev_snapshot
          LEFT JOIN legs l ON l.account_key = t.account_key;
      END IF;
    END LOOP;

    /* An account nobody has read before, or one whose last reading holds no
       snapshot (every reading before v4), is recorded, not judged. */
    v_read_at := clock_timestamp();
    INSERT INTO public.ca_account_snapshots
      (account_key, account_type, entity_id, club_id, column_name, balance, taken_at, is_baseline, basis_version, note, read_snapshot, cum_unexplained)
    SELECT t.account_key, t.account_type, t.entity_id, t.club_id, t.column_name,
           b.bal, v_read_at, true, v_basis,
           CASE WHEN p.prev_at IS NULL THEN 'baseline: first reading of this account, not judged'
                ELSE format('rebaselined onto %s: the previous reading (%s) windowed the journal by created_at, and a leg that straddled that reading is the reader''s to miss, not the account''s',
                            v_basis, COALESCE(p.prev_basis, 'the unversioned reader')) END,
           pg_current_snapshot()::text,
           0
      FROM zz_replay_touched t
      JOIN zz_replay_prev p ON p.account_key = t.account_key AND (p.prev_at IS NULL OR p.prev_snapshot IS NULL)
      CROSS JOIN LATERAL (
        SELECT public.fn_ca_account_balance(t.account_type, t.entity_id, t.club_id, t.column_name) AS bal
      ) b
     WHERE b.bal IS NOT NULL;
    GET DIAGNOSTICS v_baselines = ROW_COUNT;

    v_read_at := clock_timestamp();
    FOR r IN
      SELECT t.*, p.prev_balance, p.prev_at, p.prev_unexplained, p.prev_cum, p.prev_basis,
             d.expected, d.now_bal, d.read_at, d.read_snapshot
        FROM zz_replay_touched t
        JOIN zz_replay_prev p ON p.account_key = t.account_key
        JOIN zz_replay_read d ON d.account_key = t.account_key AND d.prev_at = p.prev_at
    LOOP
      IF r.now_bal IS NULL THEN CONTINUE; END IF;

      /* A CHANGE OF BASIS IS NOT DRIFT. */
      IF COALESCE(r.prev_basis, '') <> v_basis THEN
        INSERT INTO public.ca_account_snapshots
          (account_key, account_type, entity_id, club_id, column_name, balance, taken_at,
           is_baseline, unexplained, cum_unexplained, basis_version, note, read_snapshot)
        VALUES (r.account_key, r.account_type, r.entity_id, r.club_id, r.column_name,
                r.now_bal, v_read_at, true, NULL, 0, v_basis,
                format('rebaselined onto %s: the previous reading (%s) windowed the journal by created_at, and a leg that straddled that reading is the reader''s to miss, not the account''s',
                       v_basis, COALESCE(r.prev_basis, 'the unversioned reader')),
                r.read_snapshot);
        v_rebased := v_rebased + 1;
        CONTINUE;
      END IF;

      v_checked := v_checked + 1;
      v_this := round((r.now_bal - r.prev_balance) - r.expected, 2);
      v_cum := round(v_this + COALESCE(r.prev_cum, 0), 2);
      v_two := CASE
                 WHEN abs(v_this) >= 100 THEN v_this
                 WHEN v_this <> 0 AND COALESCE(r.prev_unexplained, 0) <> 0
                      AND sign(v_this) = sign(r.prev_unexplained) THEN v_cum
                 ELSE 0
               END;

      INSERT INTO public.ca_account_snapshots
        (account_key, account_type, entity_id, club_id, column_name, balance, taken_at,
         is_baseline, unexplained, cum_unexplained, basis_version, note, read_snapshot)
      VALUES (r.account_key, r.account_type, r.entity_id, r.club_id, r.column_name,
              r.now_bal, v_read_at, false, v_this, v_cum, v_basis,
              format('moved %s, journal %s, unexplained %s this interval (cumulative %s, judged %s) since %s',
                     round(r.now_bal - r.prev_balance, 2), r.expected, v_this, v_cum, v_two, r.prev_at),
              r.read_snapshot);

      IF abs(v_two) > 0.005 THEN
        v_bad := v_bad + 1;
        IF abs(v_two) > abs(v_worst) THEN v_worst := v_two; v_worst_key := r.account_key; END IF;
        IF v_bad <= 20 THEN
          v_sample := v_sample || jsonb_build_object('account', r.account_key, 'moved', round(r.now_bal - r.prev_balance, 2),
                                                     'journal', r.expected, 'unexplained', v_this, 'cumulative', v_cum,
                                                     'since', r.prev_at);
        END IF;
        PERFORM public.fn_ca_raise_drift_incident(
          'fn_ca_ledger_replay', 'ledger_imbalance',
          CASE WHEN abs(v_two) >= 100 THEN 'critical' ELSE 'warning' END,
          'ledger-replay:' || r.account_key || ':' || to_char(v_now, 'YYYY-MM-DD'),
          v_two, r.expected, round(r.now_bal - r.prev_balance, 2),
          'ledger', r.account_type, r.entity_id, r.club_id, NULL, NULL, NULL, NULL, NULL, NULL, NULL,
          format('%s moved %s between %s and now while the journal accounts for %s: %s unexplained this interval, %s over the last two. The journal window is the previous reading''s snapshot, so a leg is counted exactly when it committed after that reading.',
                 r.column_name, round(r.now_bal - r.prev_balance, 2), r.prev_at, r.expected, v_this, v_cum),
          false,
          jsonb_build_object('account_key', r.account_key, 'column', r.column_name,
                             'moved', round(r.now_bal - r.prev_balance, 2), 'journal', r.expected,
                             'unexplained', v_this, 'cumulative', v_cum, 'judged', v_two,
                             'previous_at', r.prev_at, 'basis_version', v_basis));
      END IF;
    END LOOP;

    /* WHAT THIS SNAPSHOT SAW (20261004135607). Under REPEATABLE READ every
       statement of this run reads the snapshot stored on its readings, so the
       legs this statement can see ARE the legs that reading saw. Only xids at
       or above the snapshot's xmin can be misjudged by pg_visible_in_snapshot
       (a subtransaction of a running transaction), and the next window only
       looks back to its previous reading minus 15 minutes. */
    IF current_setting('transaction_isolation') = 'repeatable read' THEN
      INSERT INTO public.ca_ledger_replay_readings (read_snapshot, read_at, committed_legs)
      SELECT pg_current_snapshot()::text, clock_timestamp(), COALESCE(array_agg(l.id ORDER BY l.id), '{}')
        FROM public.chip_ledger l
       WHERE l.created_at > v_now - interval '30 minutes'
         AND public.fn_ca_xid8(l.xmin) >= pg_snapshot_xmin(pg_current_snapshot())
      ON CONFLICT (read_snapshot) DO NOTHING;
    END IF;

    PERFORM public.fn_ca_kill_switch_trip('fn_ca_ledger_replay', v_worst,
      format('one account disagrees with the journal by %s (%s)', round(COALESCE(v_worst, 0), 2), COALESCE(v_worst_key, 'n/a')));

    RETURN jsonb_build_object('checked', v_checked, 'baselines', v_baselines, 'rebaselined', v_rebased,
                              'disagree', v_bad, 'worst', round(COALESCE(v_worst, 0), 2), 'worst_account', v_worst_key,
                              'unkeyable_legs', v_unkeyable, 'basis_version', v_basis,
                              'sample', v_sample, 'at', v_now);
  END;
  $function$

CREATE OR REPLACE FUNCTION public.fn_sp_digest_attention(p_day date, p_metrics jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  a jsonb := '[]'::jsonb;
  v numeric; v2 numeric; avg7 numeric; t text; r record; v_elig numeric;
  v_source_events jsonb;
  v_credit_count numeric; v_credit_unbacked numeric;
  v_drift_ids jsonb;
  prev jsonb;
  s timestamptz := (p_day::timestamp AT TIME ZONE 'America/Chicago');
  e timestamptz := ((p_day + 1)::timestamp AT TIME ZONE 'America/Chicago');
BEGIN
  SELECT metrics INTO prev FROM public.sp_daily_metrics WHERE day = p_day - 1;

  -- Money not reconciling
  v := (p_metrics#>>'{money,supply_unexplained}')::numeric;
  IF COALESCE(v,0) <> 0 THEN
    a := a || jsonb_build_object('rule','money_not_reconciling','severity','critical',
      'title', format('Chip supply has %s unexplained chips', to_char(v,'FM999,999,999,990.00')), 'detail', jsonb_build_object('unexplained', v));
  END IF;
  v := (p_metrics#>>'{health,ledger_findings}')::numeric;
  IF COALESCE(v,0) > 0 THEN
    a := a || jsonb_build_object('rule','ledger_findings','severity','critical',
      'title', format('%s new ledger invariant findings', v), 'detail', jsonb_build_object('count', v));
  END IF;
  v := (p_metrics#>>'{money,ledger_rake_utc_day}')::numeric; v2 := (p_metrics#>>'{money,rollup_rake_utc_day}')::numeric;
  IF v IS NOT NULL AND v2 IS NOT NULL AND abs(v - v2) > 1 THEN
    a := a || jsonb_build_object('rule','rake_rollup_mismatch','severity','warning',
      'title', format('Rake rollup (%s) does not match the ledger (%s)', v2, v), 'detail', jsonb_build_object('ledger', v, 'rollup', v2));
  END IF;

  -- Critical alert types that are brand new this week, or at least doubled and
  -- firing 10+ times. One grouped item; every one of these alerts is already
  -- in the fleet's inbox, so this item is not dispatched again.
  -- One bounded history pass. A correlated NOT EXISTS below an OR can
  -- rescan the large inbox once per current alert inside this PL/pgSQL call.
  WITH original_inbox AS MATERIALIZED (
    SELECT id,alertname,received_at,investigation_status,
           NOT COALESCE((source LIKE 'local.%-runtime' AND status='resolved' AND jsonb_typeof(payload->'resolves')='string'),false) AS failure_observation
      FROM public.operational_alert_events
     WHERE received_at >= s - interval '7 days' AND received_at < e
       AND severity='critical'
       AND payload->>'snapshot_kind' IS DISTINCT FROM 'update_new'
  ), history AS MATERIALIZED (
    SELECT alertname,
           count(*) FILTER (WHERE received_at >= s - interval '1 day'
                            AND investigation_status IS DISTINCT FROM 'informational') AS prior
      FROM original_inbox
     WHERE received_at < s AND failure_observation
     GROUP BY alertname
  ), prior_day AS (
    -- Keep the prior query's NULL-name-to-unknown counting semantics.
    SELECT COALESCE(alertname,'unknown') alertname, sum(prior) prior
      FROM history GROUP BY COALESCE(alertname,'unknown')
  ), source_day AS MATERIALIZED (
    SELECT COALESCE(alertname,'unknown') alertname,
      -- Old immutable metrics counted every delivery; retain their exact
      -- original cohort for status proof, while new metrics count failures.
      CASE WHEN (p_metrics#>>ARRAY['health','alert_names',COALESCE(alertname,'unknown')])::numeric
                    = count(*) FILTER(WHERE failure_observation)
           THEN COALESCE(jsonb_agg(id ORDER BY id) FILTER(WHERE failure_observation),'[]'::jsonb)
           WHEN (p_metrics#>>ARRAY['health','alert_names',COALESCE(alertname,'unknown')])::numeric=count(*)
           THEN jsonb_agg(id ORDER BY id)
           ELSE '[]'::jsonb END event_ids
      FROM original_inbox
     WHERE received_at >= s
       AND investigation_status IS DISTINCT FROM 'informational'
     GROUP BY COALESCE(alertname,'unknown')
  )
  SELECT count(*), string_agg(format('%s (%s, %s the day before)', z.alertname, z.n, z.prior), '; ' ORDER BY z.n DESC),
         jsonb_agg(jsonb_build_object('alertname',z.alertname,'expected_count',z.n,
           'event_ids',COALESCE(original.event_ids,'[]'::jsonb)) ORDER BY z.alertname)
    INTO v, t, v_source_events
    FROM (
      SELECT cur.key AS alertname, cur.value::numeric AS n, COALESCE(pd.prior,0) AS prior
        FROM jsonb_each_text(COALESCE(p_metrics#>'{health,alert_names}','{}'::jsonb)) cur
        LEFT JOIN history seen ON seen.alertname = cur.key
        LEFT JOIN prior_day pd ON pd.alertname = cur.key
       WHERE (seen.alertname IS NULL
          OR (cur.value::numeric >= 10 AND cur.value::numeric >= 2 * COALESCE(pd.prior,0)))
         -- A financial_alerts: or drift_incident: row is a mirror of an alert
         -- already counted under its own name that day (2026-11-06: 10 types
         -- were really 6). The base keeps its exact count and event ids.
         AND NOT (cur.key ~ '^(drift_incident:|financial_alerts:)'
                  AND COALESCE(p_metrics#>'{health,alert_names}','{}'::jsonb)
                      ? regexp_replace(cur.key, '^(drift_incident:)?(financial_alerts:)?', ''))
    ) z LEFT JOIN source_day original ON original.alertname = z.alertname;
  IF v > 0 THEN
    a := a || jsonb_build_object('rule','critical_alert_rising','severity','critical','dispatch',false,
      'title', format('%s critical alert type%s new this week or doubled: %s', v, CASE WHEN v = 1 THEN ' is' ELSE 's are' END, left(t, 400)),
      'detail', jsonb_build_object('count', v, 'alerts', t, 'source_events',v_source_events));
  END IF;

  SELECT count(*),jsonb_agg(id ORDER BY id) INTO v,v_drift_ids
    FROM public.ca_drift_incidents WHERE resolved_at IS NULL AND deadline_at < now();
  IF v > 0 THEN
    a := a || jsonb_build_object('rule','drift_past_deadline','severity','warning','dispatch',false,
      'title', format('%s drift incidents are open past their deadline', v),
      'detail', jsonb_build_object('count',v,'incident_ids',v_drift_ids,'as_of',now()));
  END IF;

  -- Stuck tournaments (live)
  FOR r IN SELECT id, name, tournament_type, started_at FROM public.tournaments
            WHERE status = 'RUNNING' AND started_at < now() - make_interval(hours => public.fn_sp_setting('stuck_tournament_hours',12)::int)
            ORDER BY started_at LIMIT 10 LOOP
    a := a || jsonb_build_object('rule','stuck_tournament','severity','critical',
      'title', format('%s "%s" has been running since %s', r.tournament_type, r.name, to_char(r.started_at AT TIME ZONE 'America/Chicago','Mon DD HH12:MI AM')),
      'detail', jsonb_build_object('tournament_id', r.id), 'key', r.id::text);
  END LOOP;

  -- Engine breaks and deploys
  v := (p_metrics#>>'{health,breaks,total}')::numeric - (p_metrics#>>'{health,breaks,passed}')::numeric;
  IF COALESCE(v,0) > 0 THEN
    a := a || jsonb_build_object('rule','break_failed','severity','warning','title', format('%s engine maintenance breaks did not pass', v), 'detail', p_metrics#>'{health,breaks}');
  END IF;
  v := (p_metrics#>>'{health,deploys,attempted}')::numeric - (p_metrics#>>'{health,deploys,shipped}')::numeric;
  IF COALESCE(v,0) > 0 THEN
    a := a || jsonb_build_object('rule','deploy_failed','severity','warning','title', format('%s engine deploy attempts did not ship', v), 'detail', p_metrics#>'{health,deploys}');
  END IF;

  -- Cashouts waiting (live)
  v := (SELECT count(*) FROM public.cashout_requests WHERE completed_at IS NULL AND cancelled_at IS NULL
          AND status NOT IN ('completed','cancelled','canceled','rejected','denied')
          AND created_at < now() - make_interval(hours => public.fn_sp_setting('cashout_wait_hours',24)::int));
  IF v > 0 THEN
    a := a || jsonb_build_object('rule','cashout_waiting','severity','warning','title', format('%s cashout requests waiting over 24 hours', v), 'detail', jsonb_build_object('count', v));
  END IF;

  -- Weekly invoices late (Mondays, after 9 AM Central)
  IF extract(isodow FROM (now() AT TIME ZONE 'America/Chicago')) = 1 AND (now() AT TIME ZONE 'America/Chicago')::time >= time '09:00' THEN
    v := (SELECT count(*) FROM public.settlement_invoices
           WHERE invoice_type IN ('agent_to_player','agent_to_subagent','club_to_agent','union_to_club','club_weekly_accounting')
             AND created_at > now() - interval '3 days' AND NOT COALESCE(message_sent,false));
    IF v > 0 THEN
      a := a || jsonb_build_object('rule','invoices_late','severity','warning','title', format('%s weekly invoices have not been delivered', v), 'detail', jsonb_build_object('count', v));
    END IF;
  END IF;

  v := (p_metrics#>>'{agents,agent_credit_invoices}')::numeric;
  IF COALESCE(v,0) > 0 THEN
    -- funded_credit_tracking_basis: a statement documents an actual funded
    -- wallet top-up requirement; it never grants borrowed spendable chips.
    SELECT count(*),count(*) FILTER(WHERE NOT EXISTS(
      SELECT 1 FROM public.agent_credit_weekly_basis b
      JOIN public.agent_credit_tracking_policy policy ON policy.singleton
       AND b.period_end>=policy.activated_at
      WHERE b.agent_id=i.agent_id AND b.period_start=i.period_start AND b.period_end=i.period_end
       AND b.amount_owed=GREATEST(0,b.credit_line-b.agent_wallet_before_rakeback)
       AND i.debt_owed>0 AND i.debt_owed<=b.amount_owed))
      INTO v_credit_count,v_credit_unbacked
      FROM public.credit_invoices i WHERE i.created_at>=s AND i.created_at<e;
    IF v_credit_count IS DISTINCT FROM v THEN
      a:=a||jsonb_build_object('rule','agent_on_credit','severity','warning',
        'title','Agent Invoice Tracking Evidence Is Incomplete',
        'detail',jsonb_build_object('count',v,'source_count',v_credit_count,'unbacked',v_credit_unbacked));
    ELSIF v_credit_unbacked>0 THEN
      a:=a||jsonb_build_object('rule','agent_on_credit','severity','warning',
        'title',format('%s agent invoices lack an original funded tracking basis',v_credit_unbacked),
        'detail',jsonb_build_object('count',v_credit_unbacked,'invoices_created',v));
    END IF;
  END IF;

  -- Diamond Spins and Diamond games underfunded (live)
  v := (SELECT count(*) FROM public.wheel_configs WHERE enabled AND exposure_allowance_chips < public.fn_diamond_spins_allowance_floor())
     + (SELECT count(*) FROM public.diamond_game_configs WHERE enabled AND exposure_allowance_chips < public.fn_diamond_spins_allowance_floor());
  IF v > 0 THEN
    a := a || jsonb_build_object('rule','spins_underfunded','severity','critical','title', format('%s Diamond Spins or Diamond game hosts are funded below 2,500 diamonds', v), 'detail', jsonb_build_object('count', v));
  END IF;

  -- Big diamond movements
  IF jsonb_array_length(COALESCE(p_metrics#>'{diamonds,big_movements}','[]'::jsonb)) > 0 THEN
    a := a || jsonb_build_object('rule','big_diamond_move','severity','warning',
      'title', format('%s diamond movements over %s', jsonb_array_length(p_metrics#>'{diamonds,big_movements}'), to_char(public.fn_sp_setting('big_diamond_move',10000),'FM999,999,999')),
      'detail', p_metrics#>'{diamonds,big_movements}');
  END IF;

  -- Payments
  v := COALESCE((p_metrics#>>'{sales,refunds_usd}')::numeric,0);
  v2 := COALESCE((p_metrics#>>'{sales,disputes}')::numeric,0) + COALESCE((p_metrics#>>'{sales,stripe_events,not_completed}')::numeric,0);
  IF v > 0 OR v2 > 0 THEN
    a := a || jsonb_build_object('rule','payment_problem','severity','critical',
      'title', format('Payments: %s USD refunded, %s disputes or failed Stripe events', to_char(v,'FM999,990.00'), v2), 'detail', jsonb_build_object('refunds_usd', v, 'issues', v2));
  END IF;

  -- Signups vs 7 day average (only once there is history)
  SELECT avg((metrics#>>'{growth,signups}')::numeric), count(*) INTO avg7, v2 FROM public.sp_daily_metrics WHERE day BETWEEN p_day - 7 AND p_day - 1;
  v := (p_metrics#>>'{growth,signups}')::numeric;
  IF v2 >= 3 AND avg7 >= 1 AND v < avg7 * public.fn_sp_setting('signup_drop_ratio',0.5) THEN
    a := a || jsonb_build_object('rule','signups_dropped','severity','warning',
      'title', format('%s real signups vs a 7 day average of %s', v, round(avg7,1)), 'detail', jsonb_build_object('signups', v, 'avg7', round(avg7,1)));
  END IF;
  v2 := (p_metrics#>>'{growth,signups_phone_verified}')::numeric;
  -- Measured against players who can still earn the package by phone
  -- (US, not already paid by hand); older metrics without the figure fall
  -- back to every signup.
  v_elig := COALESCE((p_metrics#>>'{growth,signups_phone_eligible}')::numeric, v);
  IF v_elig >= 2 AND v2 < v_elig * public.fn_sp_setting('phone_verify_min_rate',0.5) THEN
    a := a || jsonb_build_object('rule','phone_verification_low','severity','warning',
      'title', format('Only %s of %s eligible new players verified their phone (%s skipped the offer)', v2, v_elig,
                      COALESCE((p_metrics#>>'{growth,signups_phone_skipped}')::numeric, 0)),
      'detail', jsonb_build_object('signups', v, 'eligible', v_elig, 'verified', v2,
                                   'skipped', (p_metrics#>>'{growth,signups_phone_skipped}')::numeric,
                                   'otp_codes_sent', (p_metrics#>>'{growth,otp_codes_sent}')::numeric));
  END IF;
  IF COALESCE((p_metrics#>>'{growth,otp_send_failures}')::numeric, 0) > 0 THEN
    a := a || jsonb_build_object('rule','phone_otp_send_failed','severity','warning',
      'title', format('%s phone verification codes failed to send', (p_metrics#>>'{growth,otp_send_failures}')::numeric),
      'detail', jsonb_build_object('failed', (p_metrics#>>'{growth,otp_send_failures}')::numeric,
                                   'sent', (p_metrics#>>'{growth,otp_codes_sent}')::numeric));
  END IF;
  v := (p_metrics#>>'{health,signup_errors}')::numeric;
  IF COALESCE(v,0) > 0 THEN
    a := a || jsonb_build_object('rule','signup_errors','severity','warning','title', format('%s signup errors', v), 'detail', jsonb_build_object('count', v));
  END IF;

  -- Error spike
  SELECT avg((metrics#>>'{health,client_errors}')::numeric), count(*) INTO avg7, v2 FROM public.sp_daily_metrics WHERE day BETWEEN p_day - 7 AND p_day - 1;
  v := (p_metrics#>>'{health,client_errors}')::numeric;
  IF v2 >= 3 AND avg7 > 0 AND v > avg7 * public.fn_sp_setting('client_error_spike_ratio',2) THEN
    a := a || jsonb_build_object('rule','error_spike','severity','warning',
      'title', format('%s client errors vs a 7 day average of %s', v, round(avg7)), 'detail', jsonb_build_object('errors', v, 'avg7', round(avg7)));
  END IF;
  v := (p_metrics#>>'{health,crashes}')::numeric;
  IF COALESCE(v,0) > 0 THEN
    a := a || jsonb_build_object('rule','client_crash','severity','warning','title', format('%s app crashes', v), 'detail', jsonb_build_object('count', v));
  END IF;

  -- Beta accounts flagged
  IF jsonb_array_length(COALESCE(p_metrics#>'{health,beta_accounts_flagged}','[]'::jsonb)) > 0 THEN
    a := a || jsonb_build_object('rule','beta_accounts_flagged','severity','warning','title','KingFish or Danimal appeared in an anti-cheat signal', 'detail', p_metrics#>'{health,beta_accounts_flagged}');
  END IF;

  -- Horse fleet
  v := (p_metrics#>>'{play,horse_fleet,degraded_beats}')::numeric;
  v2 := (p_metrics#>>'{play,horse_fleet,max_stuck}')::numeric;
  -- ONE FALLBACK CYCLE IS NOT A DEGRADED FLEET (20261118165140): a degraded
  -- beat means the fleet policy read failed and that one cycle ran on the
  -- built-in defaults (today's behaviour, unchanged). One such cycle in a day
  -- (2026-11-17: 1 of 2,635 beats) paged the fleet as degraded; a run of
  -- horse_degraded_run consecutive fallback cycles is what is degraded. A
  -- metrics row from before max_degraded_run existed is read by its count.
  IF COALESCE((p_metrics#>>'{play,horse_fleet,max_degraded_run}')::numeric, v, 0) >= public.fn_sp_setting('horse_degraded_run',3) OR COALESCE(v2,0) > COALESCE((p_metrics#>>'{play,horse_fleet,max_seated}')::numeric,0) * public.fn_sp_setting('horse_stuck_ratio',0.05) THEN
    a := a || jsonb_build_object('rule','horse_fleet_degraded','severity','warning',
      'title', CASE WHEN COALESCE((p_metrics#>>'{play,horse_fleet,unknown_stuck_beats}')::numeric,-1)<>0 OR v2 IS NULL THEN format('Horse fleet degraded on %s heartbeats; stuck-horse count unavailable', COALESCE(v,0)) ELSE format('Horse fleet degraded on %s heartbeats, up to %s horses stuck', COALESCE(v,0), v2) END, 'detail', p_metrics#>'{play,horse_fleet}');
  END IF;

  -- New admins vs the prior day
  IF prev IS NOT NULL THEN
    FOR t IN SELECT j.x FROM jsonb_array_elements_text(COALESCE(p_metrics#>'{security,admin_ids}','[]'::jsonb)) AS j(x)
              WHERE NOT (COALESCE(prev#>'{security,admin_ids}','[]'::jsonb) ? x) LOOP
      a := a || jsonb_build_object('rule','new_admin','severity','critical',
        'title', format('New admin account: %s', COALESCE(p_metrics#>>ARRAY['security','admins',t], t)), 'detail', jsonb_build_object('user_id', t), 'key', t);
    END LOOP;
  END IF;

  -- Stale sources (only meaningful near the end of the day)
  FOR r IN SELECT key, value::timestamptz ts FROM jsonb_each_text(COALESCE(p_metrics->'freshness','{}'::jsonb))
            WHERE key IN ('chip_ledger','hand_history','horse_heartbeat','alert_inbox') LOOP
    IF r.ts IS NULL OR r.ts < LEAST(e, now()) - interval '2 hours' THEN
      a := a || jsonb_build_object('rule','stale_source','severity','warning',
        'title', format('%s has had no new rows since %s', replace(r.key,'_',' '), COALESCE(to_char(r.ts AT TIME ZONE 'America/Chicago','Mon DD HH12:MI AM'),'never')),
        'detail', jsonb_build_object('source', r.key, 'newest', r.ts), 'key', r.key);
    END IF;
  END LOOP;

  -- Previous morning's email
  -- Only once the digest was already running the day before; the first digest
  -- after launch has no previous morning to miss.
  IF NOT EXISTS (SELECT 1 FROM public.sp_daily_digest_runs WHERE day = p_day - 1 AND status = 'sent')
     AND EXISTS (SELECT 1 FROM public.sp_daily_digest_runs WHERE day <= p_day - 1) THEN
    a := a || jsonb_build_object('rule','digest_failed','severity','warning','title', format('The digest for %s was not delivered', to_char(p_day - 1,'Mon DD')), 'detail', '{}'::jsonb);
  END IF;

  -- Midway Free Buy rotation and promo runway (2026-11-05).
  a := a || public.fn_sp_midway_free_buy_watch();

  RETURN a;
END $function$

CREATE OR REPLACE FUNCTION public.sp_prune_hand_state_snapshots(p_batch integer DEFAULT 5000)
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
 v_cursor smarter_private.snapshot_retention_scan;
 v_seen integer := 0;
 v_page integer;
 v_page_seen integer;
 v_last_at timestamptz;
 v_last_id uuid;
 v_n integer;
 v_deleted integer := 0;
 v_limit integer := LEAST(10000, GREATEST(COALESCE(p_batch,5000),1));
 v_deadline timestamptz := clock_timestamp() + interval '20 seconds';
BEGIN
 -- SNAPSHOT RETENTION PAGES BY ITS COVERED INDEX (2026-11-19, 20261119173316).
 -- The cron already takes its advisory lock. Other callers must not race
 -- the same scan position or wait behind a long retention transaction.
 SELECT * INTO v_cursor FROM smarter_private.snapshot_retention_scan
  WHERE singleton FOR UPDATE SKIP LOCKED;
 IF NOT FOUND THEN RETURN 0; END IF;
 LOOP
  EXIT WHEN v_seen >= v_limit OR clock_timestamp() >= v_deadline;
  v_page := LEAST(1000, v_limit - v_seen);
  -- MATERIALIZED is the work boundary: the page is an index-only keyset read
  -- (idx_hand_state_snapshots_retention_cover), and only certified rows with
  -- no reserved permit ever reach the DELETE and its eligibility function.
  WITH page AS MATERIALIZED (
   SELECT s.id,s.created_at,s.table_id,s.hand_number FROM public.hand_state_snapshots s
    WHERE s.created_at >= v_cursor.through_at
      AND (s.created_at,s.id) > (v_cursor.through_at,v_cursor.after_id)
      AND s.created_at < statement_timestamp()-interval '8 days'
    ORDER BY s.created_at,s.id LIMIT v_page
  ), certified AS MATERIALIZED (
   SELECT p.id FROM page p
    WHERE EXISTS (SELECT 1 FROM smarter_private.horse_adaptive_disposal_certificates c
                   WHERE c.table_id=p.table_id AND c.hand_number=p.hand_number)
      AND NOT EXISTS (SELECT 1 FROM smarter_private.f06_hand_permits fp
                       WHERE fp.table_id=p.table_id AND fp.hand_number=p.hand_number AND fp.state='reserved')
  ), doomed AS (
   -- Same authoritative eligibility function, certificate and interrupted
   -- hand holds, rechecked by the DELETE. No human/BBJ/escrow witness relaxed.
   DELETE FROM public.hand_state_snapshots h USING certified d WHERE h.id=d.id
    AND h.updated_at < statement_timestamp()-interval '8 days'
    AND EXISTS (SELECT 1 FROM smarter_private.horse_adaptive_disposal_certificates c
                 WHERE c.table_id=h.table_id AND c.hand_number=h.hand_number)
    AND NOT EXISTS (SELECT 1 FROM smarter_private.f06_hand_permits p
                     WHERE p.table_id=h.table_id AND p.hand_number=h.hand_number AND p.state='reserved')
    AND smarter_private.horse_snapshot_disposable(h.id)
   RETURNING 1
  )
  SELECT (SELECT count(*) FROM doomed),
         (SELECT count(*) FROM page),
         (SELECT created_at FROM page ORDER BY created_at DESC,id DESC LIMIT 1),
         (SELECT id FROM page ORDER BY created_at DESC,id DESC LIMIT 1)
    INTO v_n,v_page_seen,v_last_at,v_last_id;
  EXIT WHEN v_page_seen=0;
  v_deleted := v_deleted+v_n;
  v_seen := v_seen+v_page_seen;
  v_cursor.through_at := v_last_at;
  v_cursor.after_id := v_last_id;
  EXIT WHEN v_page_seen < v_page;
 END LOOP;
 IF v_seen=0 THEN
  -- End of pass: revisit refused witnesses on the next existing cron call.
  -- They may become disposable after their original owning hand completes.
  v_cursor.through_at := '-infinity';
  v_cursor.after_id := '00000000-0000-0000-0000-000000000000';
 END IF;
 UPDATE smarter_private.snapshot_retention_scan
  SET through_at=v_cursor.through_at,after_id=v_cursor.after_id,
      examined=examined+v_seen,updated_at=clock_timestamp() WHERE singleton;
 RETURN v_deleted;
END
$function$
